INSERT INTO `tbl_competence` (`competence_id`, `competance_name`, `description`, `weight`) VALUES
(1, 'Job Knowledge/Skills', 'Demonstrates understanding of the job and applies that knowledge effectively.  Satisfactorily performs essential job functions and demonstrates required knowledge and skills.', ''),
(2, 'Quality of Work', 'Evaluate overall work results to include accuracy, thoroughness, organization, follow-up and consistency of work produced.  \nKeeps others informed about organisational plans and developments', ''),
(3, 'Initiative', 'Takes ownership of work; doing what is needed without being asked. Ability for self-direction anticipates needs and identifies problems.  Makes suggestions for more effective work methods and offers ideas for improvements.', ''),
(4, 'Accountability and Dependability', 'Accepts personal responsibility and follows through on commitments. Can be relied upon to achieve excellent results with little need for oversight. Maintains an acceptable attendance record and is punctual. ', ''),
(5, 'Productivity', 'Uses appropriate productivity tools and methods to efficiently accomplish all tasks.  Prioritizes workload effectively, completes work thoroughly, accurately and in a timely manner.', ''),
(6, ' Coachability', 'Receptive to feedback, willing to learn and embraces continuous improvement.\nabout co-operation.', ''),
(7, 'Collegiality and Respectfulness', 'Helpful, approachable and team oriented. Builds strong working relationships and a positive work environment while continually demonstrating respect and empathy for all people. Recognizes and values diversity within the workgroup and contributes to a harassment-free environment.', ''),
(8, 'Communication', 'Demonstrates the ability to express ideas, both verbally and in writing. Balances listening and talking and keeps others informed. ', ''),
(9, 'Safety', 'Follows established safety procedures, pays attention to personal safety and the safety of others.', ''),
(13, 'Customer Focus', 'Establishes and maintains a positive customer focused and student-\ncentered work environment. Strives for high customer satisfaction, going out of the way to be helpful, courteous, and pleasant. \n', '');
